[CmdletBinding()]
param([switch]$SkipMigration)

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$script:passed=0
$utf8NoBom=New-Object Text.UTF8Encoding($false)

function Assert-True([bool]$Condition,[string]$Name){if(-not $Condition){throw "ASSERT_FAIL|$Name"};$script:passed++;Write-Output "PASS|$Name"}
function Write-Text([string]$Path,[string]$Text){$parent=Split-Path -Parent $Path;if($parent -and -not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$v=$Text.Replace("`r`n","`n").Replace("`r","`n");if(-not $v.EndsWith("`n")){$v+="`n"};[IO.File]::WriteAllText($Path,$v,$utf8NoBom)}
function Write-Json([string]$Path,$Object){Write-Text $Path ($Object|ConvertTo-Json -Depth 40)}
function Get-Identity([string]$Path){$f=Get-Item -LiteralPath $Path;return $f.Length.ToString()+'|'+(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash}
function Invoke-Child([string]$Script,[string[]]$Arguments,[string]$WorkingDirectory){Push-Location $WorkingDirectory;$previous=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$out=@(& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $Script @Arguments 2>&1|ForEach-Object{[string]$_});$code=$LASTEXITCODE}finally{$ErrorActionPreference=$previous;Pop-Location};return [pscustomobject]@{Code=$code;Text=($out-join"`n");Lines=$out}}
function Clone-Object($Object){return ($Object|ConvertTo-Json -Depth 40|ConvertFrom-Json)}
function Initialize-GitFixture([string]$Path){if(-not(Test-Path -LiteralPath $Path)){New-Item -ItemType Directory -Path $Path -Force|Out-Null};$out=@(& git -C $Path init --quiet 2>&1);if($LASTEXITCODE-ne0){throw "GIT_FIXTURE_INIT_FAILED|$Path|$($out-join' ')"}}
function Get-BindingDigest($Binding){$core=[ordered]@{schemaVersion=$Binding.schemaVersion;taskId=$Binding.taskId;taskLocator=$Binding.taskLocator;taskIdentity=$Binding.taskIdentity;resourceRequirementIdentity=$Binding.resourceRequirementIdentity;adapterPolicyLocator=$Binding.adapterPolicyLocator;adapterPolicyIdentity=$Binding.adapterPolicyIdentity;actualCapabilitySet=$Binding.actualCapabilitySet;selectedQuality=$Binding.selectedQuality;selectedTools=@($Binding.selectedTools);continuity=$Binding.continuity;phase=$Binding.phase;host=$Binding.host;contextIdentity=$Binding.contextIdentity};$bytes=[Text.Encoding]::UTF8.GetBytes(($core|ConvertTo-Json -Compress -Depth 20));$sha=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')}finally{$sha.Dispose()}}

$candidateRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$draftRoot=Split-Path -Parent $candidateRoot
$leanRootScripts=Join-Path $draftRoot 'lean-root-scripts'
