$authorizationChecker=Join-Path $scriptsRoot 'check-authorization.ps1'
$taskChecker=Join-Path $scriptsRoot 'check-task-card.ps1'
$routeChecker=Join-Path $scriptsRoot 'check-controller-route.ps1'
