$stableRoot=Join-Path $frameworkRoot 'versions\1.5.2'
$stableFiles=@(Get-ChildItem -LiteralPath $stableRoot -Recurse -File|ForEach-Object{$_.FullName.Substring($stableRoot.Length+1).Replace('\','/')})
$expected=@($stableFiles+$expectedNew|Sort-Object -Unique)
$actual=@(Get-ChildItem -LiteralPath $candidateRoot -Recurse -File|ForEach-Object{$_.FullName.Substring($candidateRoot.Length+1).Replace('\','/')}|Sort-Object -Unique)
Assert-True ($expected.Count-eq40-and@(Compare-Object $expected $actual -CaseSensitive).Count-eq0) 'lean-inventory-exact40'
Assert-True ((Test-Path -LiteralPath (Join-Path $leanRootScripts 'register-project.ps1'))-and(Test-Path -LiteralPath (Join-Path $leanRootScripts 'upgrade-project.ps1'))) 'lean-root-exact2'
$releaseManifestPath=Join-Path $candidateRoot 'RELEASE_MANIFEST.json'
$releaseManifest=Get-Content -Raw -Encoding utf8 -LiteralPath $releaseManifestPath|ConvertFrom-Json
$releaseLines=New-Object 'System.Collections.Generic.List[string]';$releaseTotal=0
foreach($file in Get-ChildItem -LiteralPath $candidateRoot -Recurse -File){if($file.FullName-ceq$releaseManifestPath){continue};$relative=$file.FullName.Substring($candidateRoot.Length+1).Replace('\','/');$bytes=[IO.File]::ReadAllBytes($file.FullName);$releaseLines.Add("$relative|$($bytes.Length)|$((Get-FileHash -Algorithm SHA256 -LiteralPath $file.FullName).Hash.ToUpperInvariant())");$releaseTotal+=$bytes.Length}
$releaseLines.Sort([StringComparer]::Ordinal);$releasePayload=[Text.Encoding]::UTF8.GetBytes(($releaseLines-join"`n"));$releaseHasher=[Security.Cryptography.SHA256]::Create();try{$releaseHash=$releaseHasher.ComputeHash($releasePayload);$releaseCanonical=-join($releaseHash|ForEach-Object{$_.ToString('X2')})}finally{$releaseHasher.Dispose()}
Assert-True ([int]$releaseManifest.fileCount-eq$releaseLines.Count-and[int64]$releaseManifest.totalBytes-eq$releaseTotal-and[string]$releaseManifest.canonical-ceq$releaseCanonical) 'release-manifest-canonical'

$strictIssues=@()
foreach($file in Get-ChildItem -LiteralPath $candidateRoot -Recurse -File){$bytes=[IO.File]::ReadAllBytes($file.FullName);$text=$null;try{$text=(New-Object Text.UTF8Encoding($false,$true)).GetString($bytes)}catch{$strictIssues+=$file.FullName;continue};if(($bytes.Length-ge3-and$bytes[0]-eq0xEF-and$bytes[1]-eq0xBB-and$bytes[2]-eq0xBF)-or$text.Contains("`r")-or$text.Contains([char]0)-or$text.Contains([char]0xFFFD)-or-not$text.EndsWith("`n")){$strictIssues+=$file.FullName}}
Assert-True ($strictIssues.Count-eq0) 'strict-utf8-lf'
$jsonIssues=@();foreach($file in Get-ChildItem -LiteralPath $candidateRoot -Recurse -Filter '*.json' -File){if($file.FullName-like'*project-starter\project.json'-or$file.FullName-like'*project-starter\controller.json'){continue};try{$null=Get-Content -Raw -Encoding utf8 -LiteralPath $file.FullName|ConvertFrom-Json}catch{$jsonIssues+=$file.FullName}}
Assert-True ($jsonIssues.Count-eq0) 'json-parse'
$syntaxIssues=@();foreach($file in @((Get-ChildItem -LiteralPath $scriptsRoot -Filter '*.ps1' -File)+(Get-ChildItem -LiteralPath $leanRootScripts -Filter '*.ps1' -File)+(Get-ChildItem -LiteralPath $PSScriptRoot -Filter '*.ps1' -File))){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($file.FullName,[ref]$t,[ref]$e);if($e.Count){$syntaxIssues+=$file.FullName}}
