$consumerFiles=@('LOAD_MANIFEST.json','RELEASE_MANIFEST.json','scripts/check-authorization.ps1','scripts/check-controller-route.ps1','scripts/check-remote-batch.ps1','scripts/check-task-card.ps1','scripts/invoke-protected-safe-git.ps1','scripts/resolve-load-plan.ps1','scripts/resolve-resource-binding.ps1')
$badConsumer=@();foreach($relative in $consumerFiles){$text=Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $candidateRoot $relative);if($text-match'framework/drafts/1\.6\.0/(candidate|root-scripts)' -or $text-match'REMOTE_TRANSACTION_SCHEMA|check-remote-transaction'){$badConsumer+=$relative}}
Assert-True ($badConsumer.Count-eq0) 'old-tree-zero-consumer'
$taskTemplateText=Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $candidateRoot 'TASK_TEMPLATE.md');Assert-True ($taskTemplateText.Contains('"resourceBindingLocator": ".tmp/resource-bindings/<TASK-ID>.resource-binding.json"')-and-not$taskTemplateText.Contains('"resourceBindingLocator": ".tmp/<TASK-ID>.resource-binding.json"')) 'resource-template-locator-compatible'

