    $result=Invoke-Child $protectedGit @('-ProjectRoot',$projectRoot,'-Operation','INDEX','-AllowPath','src/core/a.js','-ExpectedProjectConfigIdentity',('1|'+('0'*64)),'-PlanOnly') $tempRoot;Assert-True ($result.Code-ne0-and$result.Text-like'*CONFIG_IDENTITY_DRIFT*') 'protected-config-drift'

